//! Client-side tracking of A2A conversation identifiers.
//!
//! Per the [A2A specification](https://a2a-protocol.org/latest/specification/),
//! `contextId` and `taskId` are generated by the *server*; a client continues a
//! conversation by echoing them back on its next message. Rig's model never
//! sees them: the host records the ids issued for each conversation and
//! re-attaches them, so a model can neither forge an id nor lose one.
//!
//! The store lives on [`A2AClient`](crate::A2AClient) rather than on a tool or
//! a hook, so every surface reaching one remote agent — the tool bridge, the
//! [`A2AModel`](crate::model::A2AModel), and any number of Rig agents built
//! from them — shares one view of each conversation.

use std::sync::{Arc, Mutex};

use a2a::{SendMessageResponse, TaskState};
use indexmap::{IndexMap, IndexSet};

use crate::parts::state_label;

/// Conversations retained per client before the least recently used one is
/// evicted.
///
/// Conversation keys are caller-controlled, so an unbounded map would grow for
/// the process lifetime of a long-lived service. Eviction is observable: the
/// next call under an evicted key starts a fresh remote conversation.
pub(crate) const MAX_TRACKED_CONVERSATIONS: usize = 1024;

/// Standing-context fingerprints retained per conversation.
///
/// A long conversation with per-turn retrieval would otherwise accumulate one
/// fingerprint per retrieved document forever. Eviction only costs a resend:
/// the oldest chunk is offered to the remote again, never withheld.
pub(crate) const MAX_TRACKED_CONTEXT_CHUNKS: usize = 64;

/// Key that threads successive A2A requests into one remote conversation.
///
/// Insert it into a run's [`ToolContext`](rig_agent::tool::ToolContext) — most
/// simply via [`conversation_context`](crate::conversation_context) — to have
/// the A2A tool attach the server-issued `contextId`, and a paused task's
/// `taskId`, to later calls. Without one, every call is an independent
/// single-turn exchange.
///
/// This is deliberately independent of the conversation id Rig uses for
/// [conversation memory](rig_core::memory::ConversationMemory). Passing the
/// same string to both keeps a Rig conversation and its remote A2A counterpart
/// aligned, but Rig does not reconcile them for you.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct ConversationId(pub String);

impl ConversationId {
    /// Wrap an id.
    pub fn new(id: impl Into<String>) -> Self {
        Self(id.into())
    }

    /// Borrow the id as text.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for ConversationId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl From<String> for ConversationId {
    fn from(id: String) -> Self {
        Self(id)
    }
}

impl From<&str> for ConversationId {
    fn from(id: &str) -> Self {
        Self(id.to_string())
    }
}

/// The A2A identifiers behind one request, published as host-only result
/// metadata.
///
/// The A2A tool attaches this to every call that reaches the remote through
/// [`ToolContext::insert_result`](rig_agent::tool::ToolContext::insert_result),
/// including one whose task came back failed, so hooks can trace or externally
/// persist the remote ids. A call rejected before it is sent, or one that fails
/// in transport, carries no identifiers to publish. It is never sent to the
/// model.
///
/// ```
/// use rig_a2a::A2AThreadInfo;
/// use rig_agent::agent::{AgentHook, HookContext, ToolResultAction, ToolResultEvent};
///
/// struct LogA2AIds;
///
/// impl AgentHook for LogA2AIds {
///     async fn on_tool_result(
///         &self,
///         _context: &HookContext,
///         event: ToolResultEvent<'_>,
///     ) -> ToolResultAction {
///         if let Some(info) = event.tool_context.result::<A2AThreadInfo>() {
///             tracing::info!(
///                 context_id = ?info.context_id,
///                 state = ?info.state_label(),
///                 "a2a turn"
///             );
///         }
///         // Observe only: leave the model-visible output untouched.
///         ToolResultAction::Keep
///     }
/// }
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct A2AThreadInfo {
    /// Server-issued `contextId` carried by the response, when present.
    pub context_id: Option<String>,
    /// Server-issued `taskId` carried by the response, when present. This is
    /// reported whether or not the id was retained for reuse — see
    /// [`resumable`](Self::resumable).
    pub task_id: Option<String>,
    /// State of the responding task, or `None` for a bare `Message` response.
    pub state: Option<TaskState>,
    /// Whether the task id was retained so a later request in the same
    /// conversation resumes this task.
    pub resumable: bool,
}

impl A2AThreadInfo {
    /// Identifiers for an event that names a task and reports its state.
    pub(crate) fn for_task(context_id: &str, task_id: &str, state: &TaskState) -> Self {
        Self {
            context_id: Some(context_id.to_string()),
            task_id: Some(task_id.to_string()),
            state: Some(state.clone()),
            resumable: is_resumable(state),
        }
    }

    /// Read the identifiers off a response.
    pub(crate) fn from_response(response: &SendMessageResponse) -> Self {
        match response {
            SendMessageResponse::Task(task) => {
                Self::for_task(&task.context_id, &task.id, &task.status.state)
            }
            SendMessageResponse::Message(message) => Self {
                context_id: message.context_id.clone(),
                task_id: message.task_id.clone(),
                state: None,
                resumable: false,
            },
        }
    }

    /// Human-readable state label, for logs and error messages.
    pub fn state_label(&self) -> Option<&'static str> {
        self.state.as_ref().map(state_label)
    }
}

/// Whether a task in this state accepts a follow-up message on the same task.
///
/// Only `input-required` qualifies. A terminal task rejects further messages
/// (and a server that accepts one replays the stale completed task), while a
/// `working` or `submitted` task is still executing and answers a second
/// message with "task execution is already in progress". `auth-required` is
/// technically resumable but needs out-of-band action that a model cannot
/// take, so the id is not retained for automatic reuse.
pub(crate) fn is_resumable(state: &TaskState) -> bool {
    matches!(state, TaskState::InputRequired)
}

/// Identifiers echoed back to continue a conversation, plus what standing
/// context the remote already holds under them.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub(crate) struct Thread {
    pub(crate) context_id: Option<String>,
    pub(crate) task_id: Option<String>,
    /// Fingerprints of the preamble and context documents already delivered
    /// under `context_id`. See [`ThreadStore::record_sent_context`].
    pub(crate) sent_context: IndexSet<u64>,
}

/// Bounded, least-recently-used map of conversation key to remote identifiers.
///
/// Cloning shares the map: one store is created per [`A2AClient`] and captured
/// by every surface built from it.
///
/// [`A2AClient`]: crate::A2AClient
#[derive(Clone, Default)]
pub(crate) struct ThreadStore {
    inner: Arc<Mutex<IndexMap<String, Thread>>>,
}

impl ThreadStore {
    /// A poison-tolerant guard. A poisoned cache is still a usable cache, and
    /// the workspace lints forbid unwrapping.
    fn lock(&self) -> std::sync::MutexGuard<'_, IndexMap<String, Thread>> {
        self.inner.lock().unwrap_or_else(|error| error.into_inner())
    }

    /// Identifiers to attach to the next request in `conversation`.
    ///
    /// The guard is released before this returns, so callers never hold it
    /// across an await.
    pub(crate) fn get(&self, conversation: &ConversationId) -> Thread {
        self.lock()
            .get(conversation.as_str())
            .cloned()
            .unwrap_or_default()
    }

    /// Record the identifiers a server issued for `conversation`.
    ///
    /// The `contextId` is always retained, so a failed turn does not silently
    /// drop the conversation. The `taskId` is retained only when the task can
    /// actually be resumed (see [`is_resumable`]); otherwise it is cleared so a
    /// later request starts a new task within the same context.
    pub(crate) fn record(&self, conversation: &ConversationId, info: &A2AThreadInfo) {
        let mut store = self.lock();
        let mut thread = store
            .shift_remove(conversation.as_str())
            .unwrap_or_default();
        if let Some(context_id) = &info.context_id {
            thread.context_id = Some(context_id.clone());
        }
        thread.task_id = if info.resumable {
            info.task_id.clone()
        } else {
            None
        };
        store.insert(conversation.0.clone(), thread);
        evict_least_recently_used(&mut store);
    }

    /// Note that `fingerprints` worth of standing context reached the remote
    /// under `conversation`.
    ///
    /// Rig rebuilds a request's preamble and documents on every turn, because a
    /// stateless provider only ever sees the current request. A threaded remote
    /// keeps everything sent under one `contextId`, so a later turn sends only
    /// the chunks these fingerprints do not already cover.
    ///
    /// Recorded after the remote answers, never at build time: a turn that
    /// never landed must offer its context again.
    pub(crate) fn record_sent_context(&self, conversation: &ConversationId, fingerprints: &[u64]) {
        if fingerprints.is_empty() {
            return;
        }
        let mut store = self.lock();
        let thread = store.entry(conversation.0.clone()).or_default();
        thread.sent_context.extend(fingerprints.iter().copied());
        while thread.sent_context.len() > MAX_TRACKED_CONTEXT_CHUNKS {
            thread.sent_context.shift_remove_index(0);
        }
        evict_least_recently_used(&mut store);
    }
}

fn evict_least_recently_used(store: &mut IndexMap<String, Thread>) {
    while store.len() > MAX_TRACKED_CONVERSATIONS {
        if let Some((evicted, _)) = store.shift_remove_index(0) {
            tracing::debug!(
                target: "rig_a2a",
                conversation = %evicted,
                "evicted least recently used A2A conversation; the next call under this key starts a new remote conversation"
            );
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn info(state: TaskState) -> A2AThreadInfo {
        A2AThreadInfo {
            context_id: Some("ctx-1".to_string()),
            task_id: Some("task-1".to_string()),
            resumable: is_resumable(&state),
            state: Some(state),
        }
    }

    #[test]
    fn task_id_is_retained_only_for_input_required() {
        let states = [
            TaskState::Unspecified,
            TaskState::Submitted,
            TaskState::Working,
            TaskState::Completed,
            TaskState::Failed,
            TaskState::Canceled,
            TaskState::InputRequired,
            TaskState::Rejected,
            TaskState::AuthRequired,
        ];
        for state in states {
            let store = ThreadStore::default();
            let conversation = ConversationId::new("c");
            store.record(&conversation, &info(state.clone()));
            let thread = store.get(&conversation);
            assert_eq!(
                thread.context_id.as_deref(),
                Some("ctx-1"),
                "contextId must be retained for {state:?}"
            );
            assert_eq!(
                thread.task_id.is_some(),
                state == TaskState::InputRequired,
                "unexpected taskId retention for {state:?}"
            );
        }
    }

    #[test]
    fn resuming_a_task_then_completing_clears_the_task_id() {
        let store = ThreadStore::default();
        let conversation = ConversationId::new("c");
        store.record(&conversation, &info(TaskState::InputRequired));
        assert!(store.get(&conversation).task_id.is_some());

        store.record(&conversation, &info(TaskState::Completed));
        let thread = store.get(&conversation);
        assert_eq!(thread.context_id.as_deref(), Some("ctx-1"));
        assert!(
            thread.task_id.is_none(),
            "a completed task must not be resumed"
        );
    }

    #[test]
    fn a_message_response_records_only_the_context() {
        let store = ThreadStore::default();
        let conversation = ConversationId::new("c");
        store.record(
            &conversation,
            &A2AThreadInfo {
                context_id: Some("ctx-9".to_string()),
                // A bare Message carries no TaskState, so terminality is
                // unknowable and the id must not be reused.
                task_id: Some("task-9".to_string()),
                state: None,
                resumable: false,
            },
        );
        let thread = store.get(&conversation);
        assert_eq!(thread.context_id.as_deref(), Some("ctx-9"));
        assert_eq!(thread.task_id, None);
    }

    #[test]
    fn recording_a_turn_keeps_the_context_already_delivered() {
        let store = ThreadStore::default();
        let conversation = ConversationId::new("c");
        store.record(&conversation, &info(TaskState::Completed));
        store.record_sent_context(&conversation, &[1, 2]);

        store.record(&conversation, &info(TaskState::Completed));
        let sent = store.get(&conversation).sent_context;
        assert!(sent.contains(&1) && sent.contains(&2));
    }

    #[test]
    fn context_fingerprints_are_bounded_by_dropping_the_oldest() {
        let store = ThreadStore::default();
        let conversation = ConversationId::new("c");
        let fingerprints: Vec<u64> = (0..=MAX_TRACKED_CONTEXT_CHUNKS as u64).collect();
        store.record_sent_context(&conversation, &fingerprints);

        let sent = store.get(&conversation).sent_context;
        assert_eq!(sent.len(), MAX_TRACKED_CONTEXT_CHUNKS);
        // Dropping the oldest only costs a resend, never a withheld document.
        assert!(!sent.contains(&0));
        assert!(sent.contains(&(MAX_TRACKED_CONTEXT_CHUNKS as u64)));
    }

    #[test]
    fn conversations_are_isolated() {
        let store = ThreadStore::default();
        store.record(&ConversationId::new("a"), &info(TaskState::Completed));
        assert_eq!(store.get(&ConversationId::new("b")), Thread::default());
    }

    #[test]
    fn unknown_conversations_start_empty() {
        let store = ThreadStore::default();
        assert_eq!(store.get(&ConversationId::new("nope")), Thread::default());
    }

    #[test]
    fn eviction_is_least_recently_used() {
        let store = ThreadStore::default();
        for index in 0..MAX_TRACKED_CONVERSATIONS {
            store.record(
                &ConversationId::new(index.to_string()),
                &info(TaskState::Completed),
            );
        }
        // Touch the oldest key so it is no longer the eviction candidate.
        store.record(&ConversationId::new("0"), &info(TaskState::Completed));
        store.record(
            &ConversationId::new("overflow"),
            &info(TaskState::Completed),
        );

        assert!(store.get(&ConversationId::new("0")).context_id.is_some());
        assert!(store.get(&ConversationId::new("1")).context_id.is_none());
        assert!(
            store
                .get(&ConversationId::new("overflow"))
                .context_id
                .is_some()
        );
    }
}
